  "resume": "La classe défense du lycée André‑Honnorat a organisé le 18 juin 2026 une cérémonie nationale de l’Appel du 18 juin, au cours de laquelle les élèves de 3ᵉ ont rédigé des textes commémoratifs sur cinq résistants fusillés en 1944. Deux d’entre eux ont été décorés de gants blancs et de drapeaux de l’Amicale des Résistants lors de la même cérémonie. La manifestation a été marquée par la présence du lieutenant‑colonel Eric Biasotto,",
